"""Build a result-led report from the frozen replay outputs; no model load."""
import json,math
from pathlib import Path

ROOT=Path(__file__).resolve().parent
LABELS={'zero':'Zero-shot','random_11':'Random 11','random_29':'Random 29','random_47':'Random 47','lexical':'Full-pool lexical','mmr':'Full-pool MMR','diverse_core':'Text-diverse core','model_core':'Model-conditioned core'}
def pct(x):return f'{100*x:.2f}%'
def pp(x):return f'{100*x:+.2f} pp'
def interval(x):return '['+', '.join(pp(a) for a in x)+']'
def report():
 original=json.loads((ROOT/'results.json').read_text());follow=json.loads((ROOT/'followup_results.json').read_text());pre=json.loads((ROOT/'followup_preselect_trace.json').read_text());matrix=pre['matrix']
 paths=[(a,b,c) for a in range(16) for b in range(16) for c in range(16) if len({a,b,c})==3 and matrix[a][b] and matrix[b][c]]
 violations=[p for p in paths if not matrix[p[0]][p[2]]]
 primary=follow['comparisons']['lexical'];gate=follow['primary_gate'];memories=[original['phases'][p]['memory']['mlx_peak_active_bytes'] for p in ['dev','test']]+[pre['meta']['mlx_peak_active_bytes'],follow['memory']['mlx_peak_active_bytes']]
 diagnostic=json.loads((ROOT/'readout_probe_results.json').read_text());memories.append(diagnostic['meta']['mlx_peak_active_bytes'])
 lines=['# Demonstration preselection and answer-position audit','','Adel Mansour · 19 November 2026','','This study tests whether model-conditioned demonstration preselection improves exact recognition of small signed programs. It also checks whether conditional success relations reflect informative examples or a biased answer readout. It follows Mengyue Yang and colleagues’ [FEEDER paper, ICML 2025](https://proceedings.mlr.press/v267/jin25i.html). The code is an inspired direct-coverage alternative, not a reproduction of FEEDER’s tree or a claim of a general reasoning breakthrough.','','## Result that holds up','']
 if gate['passed']:
  lines.append('The predeclared lexical-comparator gate passed: pooled model-core accuracy was '+pct(follow['accuracy']['model_core'])+' versus '+pct(follow['accuracy']['lexical'])+', a paired difference of '+pp(primary['difference'])+' with 95% group-bootstrap interval '+interval(primary['paired_group_95_interval'])+'.')
 else:
  lines.append('The predeclared demonstration-selection improvement gate **did not pass**. On 32 fresh program groups, pooled model-core accuracy was '+pct(follow['accuracy']['model_core'])+' versus '+pct(follow['accuracy']['lexical'])+' for full-pool lexical retrieval: '+pp(primary['difference'])+', 95% paired group-bootstrap interval '+interval(primary['paired_group_95_interval'])+'. There is no confirmed improvement from the proposed preselection method.')
 lines+=['','The first frozen readout selected A on every pool, development and confirmation prompt. All eight methods therefore scored 32/128 on its balanced confirmation cohort. The original result is retained, rather than replaced by the follow-up. A four-case development diagnostic isolated an explicit answer-prefix/label-token effect. The independently frozen follow-up uses the standard model wrapper and counterbalanced option pooling. Its results are not compared with the original generation study as a reasoning improvement.','','## Fresh confirmation with strong baselines','','Each method uses the same local Qwen3-1.7B four-bit checkpoint. The fresh cohort contains 32 disjoint coefficient vectors, balanced over four domains, two wordings and four base answer positions. Each target is scored at four cyclic candidate orders. Probabilities over the four allowed labels are mapped back to candidate identity and averaged; ties within 1e-6 abstain and count as wrong. Thus rotations are repeated measurements, not 128 independent cases.','','| Method | Pooled exact choices /32 | Pooled accuracy | Fixed-order accuracy | Input tokens over four orders |','|---|---:|---:|---:|---:|']
 for a,label in LABELS.items():lines.append(f"| {label} | {round(32*follow['accuracy'][a])}/32 | {pct(follow['accuracy'][a])} | {pct(follow['fixed_order_accuracy'][a])} | {follow['input_tokens'][a]:,} |")
 lines+=['','The primary contrast was fixed as model-core minus full-pool lexical. It required at least ten percentage points gain, a strictly positive paired 95% lower confidence bound and at most 10% extra realised input tokens. The observed token ratio was '+f"{gate['token_ratio']:.4f}"+'. Passing a single comparison would not establish superiority over every baseline. The simultaneous seven-comparator gate '+('passed.' if follow['all_baselines_gate'] else '**did not pass**.'),'','| Model-core minus comparator | Difference | Paired 95% interval | Simultaneous 95% interval |','|---|---:|---|---|']
 for a,v in follow['comparisons'].items():lines.append(f"| {LABELS[a]} | {pp(v['difference'])} | {interval(v['paired_group_95_interval'])} | {interval(v['simultaneous_95_interval'])} |")
 lines+=['', 'Some paired outcome vectors are identical on this finite cohort, producing a zero-width empirical-bootstrap interval. That does not establish population equivalence. A supplementary [exact empirical-bootstrap sensitivity check](bootstrap_sensitivity.json) computes the discrete resampling distribution without Monte Carlo. It shifts the primary lower endpoint from -15.625 to -12.5 points and the secondary lower endpoint from +9.375 to +12.5 points. The frozen 20,000-resample intervals remain the primary values; neither substantive verdict changes.']
 second=follow['secondary_pooling_vs_fixed_lexical']
 lines+=['','The secondary lexical pooling-minus-fixed-order difference was '+pp(second['difference'])+', interval '+interval(second['paired_group_95_interval'])+'. Pooling costs four scored orders rather than one. This is a readout quality–cost comparison, not a selection effect or free accuracy gain. A hand-coded parser of this declared synthetic grammar answers 32/32; it is a task ceiling, not a general natural-language solution.','','## Conditional success and sufficiency checks','','The corrected singleton table had '+str(sum(map(sum,matrix)))+' correct edges out of 240 and '+str(len(violations))+' failures of transitive inference among '+str(len(paths))+' distinct two-edge paths. These paths share cases and are not independent observations. The relation here is operational conditional answer correctness; it is not FEEDER’s complete causal sufficiency/necessity definition. In particular, a target may already be answered correctly without its demonstration.','','The original all-A readout had 60 correct singleton edges, 168 two-edge paths and zero distinct-triple violations, although changing demonstrations never changed a predicted choice. Logits did change. [An exact negative control](negative_control.py) shows why transitivity alone can be vacuous: for a demo-insensitive predictor, conditional correctness depends only on the target; the reflexive completion of that relation is transitive at any accuracy. The checker exhausts all 511 binary correctness assignments up to eight targets. This is a small diagnostic argument, with no priority claim and no refutation of FEEDER.','','The paper’s [Appendix A3 and A10.1](https://arxiv.org/html/2506.06033v1) motivate testing transitivity; its geographical example demonstrates one favourable instance. The present bounded program task examines a different setting. Any explored counterexample is conditional on this checkpoint, prompt, decoder and training pool.']
 witness=ROOT/'witness_followup_results.json'
 if witness.exists():
  w=json.loads(witness.read_text());lines+=['','### Exploratory witness check','','The separately frozen [witness protocol](WITNESS_PROTOCOL.md) additionally requires zero-shot failures on both intermediate and final target before counting a canonical chain. Exact outcomes and option-position robustness are recorded in [witness results](witness_followup_results.json). This diagnostic was selected after inspecting the earlier pool relation; it does not supply an independent estimate of a population violation rate.', '', str(w['eligible_baseline_conditioned_triples'])+' canonical triples passed the zero-shot filter. The first '+str(w['selected_triples'])+' were tested at two changed option orders, producing '+str(w['rotated_configurations'])+' dependent configurations. Only '+str(w['strict_surviving_configurations'])+' configuration retained the pattern with both zero-shot controls wrong, and '+str(w['triples_strictly_surviving_both_rotations'])+' triples survived both changed orders. No stable option-position-controlled witness is claimed. The diagnostic added '+str(w['costs']['zero_shot']['calls'])+' zero-shot and '+str(w['costs']['rotated_edges']['calls'])+' deduplicated edge calls.']
 lines+=['','## Cost, memory and verification','','The original study scored 240 singleton, 96 development and 1,024 confirmation prompts. The development readout diagnostic scored 32 prompts and two full-wrapper comparisons. The follow-up scored 240 new singleton and 1,024 fresh confirmation prompts. Checkpoint loading and warmup checks are additional work; phase timing excludes them. Offline preselection tokens and elapsed time remain in the raw traces. Halving the retrieval pool does not halve prompt inference, because every nonzero context still contains two demonstrations. No end-to-end efficiency gain is claimed.','','The maximum observed MLX allocation across these recorded phases and the diagnostic was '+f'{max(memories)/1024**3:.2f} GiB'+'. Model runs were sequential, batch one, with a 128 MiB allocator cache and a 2.5 GiB allocation guideline plus observed-allocation abort checks. MLX allocation and process RSS are distinct; neither is total system RAM. Existing local weights were used without downloads.','','The first warmup’s overly strict numerical-identity tolerance failed before any experiment outcome. That failure and the corrected freeze are preserved. Representative development comparisons had the same decisions but up to .75 logit differences between chunked and full-forward scoring, so the follow-up uses the standard full wrapper. It does not claim the two implementations are numerically identical.','','The frozen follow-up CLI’s direct Python-object comparison has a JSON integer-key/string-key mismatch in raw position counts. The separate verify_followup.py wrapper normalises JSON keys before exact comparison. Frozen inference source and all reported outcomes are unchanged. Use that documented wrapper for replay.', '', 'The independent auditors verify hashes, exact grammar, split disjointness, domain/label counterbalance, gold-independent selection, raw-logit argmax, cyclic pooling, abstentions and reported counts. They include 1,007 independent pooling fixtures. Bootstrap intervals are conditional on the fixed checkpoint, training pool, coreset and synthetic generator. No additional training seeds, natural benchmark replication or human comparison were run.','','## Reproduce without loading a model','','```sh','python demo-selection/study.py analyse --verify demo-selection/results.json','python demo-selection/independent_audit.py','python demo-selection/negative_control.py','python demo-selection/verify_followup.py','python demo-selection/followup_audit.py','python demo-selection/witness_followup.py analyse --verify demo-selection/witness_followup_results.json','python demo-selection/bootstrap_sensitivity.py','```','','Inference instructions and exact guards are in [the first protocol](PROTOCOL.md) and [the follow-up protocol](FOLLOWUP_PROTOCOL.md). Completed traces are never overwritten. Synthetic questions, candidate vectors, raw four-label logits, selected demonstration IDs, hashes and costs are public; no model weights or personal data are included.']
 (ROOT/'REPORT.md').write_text('\n'.join(lines)+'\n')
def plot():
 from reportlab.graphics.shapes import Drawing,String,Line
 from reportlab.graphics.charts.barcharts import HorizontalBarChart
 from reportlab.graphics import renderSVG,renderPDF
 from reportlab.lib.colors import HexColor
 r=json.loads((ROOT/'followup_results.json').read_text());arms=list(reversed(LABELS))
 d=Drawing(970,400)
 d.add(String(30,376,'32 fresh program groups, four option orders',fontName='Helvetica-Bold',fontSize=13))
 chart=HorizontalBarChart();chart.x=165;chart.y=55;chart.width=290;chart.height=285
 chart.data=[[100*r['accuracy'][a] for a in arms]];chart.categoryAxis.categoryNames=[LABELS[a] for a in arms]
 chart.categoryAxis.labels.fontName='Helvetica';chart.categoryAxis.labels.fontSize=9
 chart.valueAxis.valueMin=0;chart.valueAxis.valueMax=100;chart.valueAxis.valueStep=25
 chart.valueAxis.labels.fontSize=9;chart.bars[0].fillColor=HexColor('#54799c');chart.bars[0].strokeColor=None
 d.add(chart);d.add(Line(165+290*.25,55,165+290*.25,340,strokeColor=HexColor('#777777'),strokeDashArray=[3,3]))
 d.add(String(200,25,'Exact program recognition (%)',fontSize=10))
 d.add(String(30,355,'Dashed line: uniform-guess reference',fontSize=9,fillColor=HexColor('#666666')))
 d.add(String(515,376,'Model core minus comparator',fontName='Helvetica-Bold',fontSize=13))
 comparisons=list(r['comparisons']);low=min(v['paired_group_95_interval'][0]*100 for v in r['comparisons'].values());high=max(v['paired_group_95_interval'][1]*100 for v in r['comparisons'].values())
 lo=math.floor(min(low,0)/10)*10-5;hi=math.ceil(max(high,0)/10)*10+5
 def xp(v):return 675+(v-lo)/(hi-lo)*265
 d.add(Line(xp(0),55,xp(0),340,strokeColor=HexColor('#999999'),strokeDashArray=[3,3]))
 for i,a in enumerate(comparisons):
  y=320-i*35;v=r['comparisons'][a];x=xp(100*v['difference']);xl=xp(100*v['paired_group_95_interval'][0]);xh=xp(100*v['paired_group_95_interval'][1])
  d.add(String(515,y-3,LABELS[a],fontSize=9));d.add(Line(xl,y,xh,y,strokeColor=HexColor('#287a72'),strokeWidth=1.5));d.add(Line(xl,y-4,xl,y+4,strokeColor=HexColor('#287a72')));d.add(Line(xh,y-4,xh,y+4,strokeColor=HexColor('#287a72')));d.add(Line(x,y-4,x,y+4,strokeColor=HexColor('#173c38'),strokeWidth=3))
 for tick in range(math.ceil(lo/10)*10,math.floor(hi/10)*10+1,10):
  x=xp(tick);d.add(Line(x,50,x,55,strokeColor=HexColor('#555555')));d.add(String(x-7,37,str(tick),fontSize=8))
 d.add(String(675,15,'Percentage points; paired 95% group-bootstrap intervals',fontSize=8))
 renderSVG.drawToFile(d,str(ROOT/'results.svg'));renderPDF.drawToFile(d,str(ROOT/'results-figure.pdf'))
if __name__=='__main__':report();plot();print('Wrote report and standalone scientific figures from verified outcomes.')
